(function(root){
'use strict';
const overlap=(a,b)=>a.x<b.x+b.w&&a.x+a.w>b.x&&a.y<b.y+b.h&&a.y+a.h>b.y;
const center=o=>({x:o.x+o.w/2,y:o.y+o.h/2});
function attendance(m,t){const a=m.attendance[t]||{kind:'unknown',attended:null,total:null};return a.total>0&&a.attended!==null?Math.max(0,Math.min(1,a.attended/a.total)):({regular:.9,sometimes:.5,rarely:.15,unknown:.45}[a.kind]??.45)}
function attendanceText(m,t){const a=m.attendance[t]||{};return a.total>0&&a.attended!==null?`${a.attended}/${a.total} events`:({regular:'Frequent',sometimes:'Sometimes',rarely:'Rarely',unknown:'Unknown'}[a.kind]||'Unknown')}
function slotsFor(traps){let slots=[];for(const t of traps){for(let x=-6;x<=8;x+=2)for(let y=-6;y<=8;y+=2){let s={id:`s${t.id}_${x}_${y}`,x:x+t.x,y:y+t.y,w:2,h:2,trap:t.id};if(overlap(s,t))continue;const c=center(s),tc=center(t);s.row=Math.max(1,Math.ceil((Math.max(Math.abs(c.x-tc.x),Math.abs(c.y-tc.y))-1.5)/2));slots.push(s)}}return slots}
function coord(state,s){const traps=state.traps,trap=traps.find(t=>t.id===s.trap)||[...traps].sort((a,b)=>Math.hypot(s.x-a.x,s.y-a.y)-Math.hypot(s.x-b.x,s.y-b.y))[0];const t1=traps.find(t=>t.id===1)||{x:0,y:0};if(trap?.id===2){const ax=Number.isFinite(state.settings.anchor2X)?state.settings.anchor2X:state.settings.anchorX+trap.x-t1.x,ay=Number.isFinite(state.settings.anchor2Y)?state.settings.anchor2Y:state.settings.anchorY+trap.y-t1.y;return{x:ax+s.x-trap.x,y:ay+s.y-trap.y}}return{x:state.settings.anchorX+s.x-(trap?.x||0),y:state.settings.anchorY+s.y-(trap?.y||0)}}
function suggest(state,trapFilter='all'){
const members=JSON.parse(JSON.stringify(state.members));const slots=state.slots;
const affected=m=>trapFilter==='all'||String(m.trap)===String(trapFilter);
const occupied=new Set(members.filter(m=>m.slot&&(!affected(m)||m.locked)).map(m=>m.slot));
const list=members.filter(m=>affected(m)&&!m.locked).sort((a,b)=>attendance(b,b.trap)-attendance(a,a.trap)||b.priority-a.priority||a.name.localeCompare(b.name));
let changes=[];
for(const m of list){const old=m.slot;const available=slots.filter(s=>s.trap===m.trap&&!occupied.has(s.id)&&!state.blocks.some(b=>overlap(s,b))&&!state.structures.some(b=>overlap(s,b)));
available.sort((a,b)=>{const score=s=>s.row*100+(s.id===old?-1:0)+Math.hypot(s.x-state.traps.find(t=>t.id===m.trap).x,s.y-state.traps.find(t=>t.id===m.trap).y)*.01;return score(a)-score(b)});
m.slot=available[0]?.id||null;if(m.slot)occupied.add(m.slot);
if(old!==m.slot){m.confirmed=false;m.verified=false;changes.push({id:m.id,name:m.name,old,slot:m.slot,reason:`${attendanceText(m,m.trap)} at BT ${m.trap} · Activity-first placement`})}}
return {members,changes};}
function validate(s){if(!s||s.version!==1||!Array.isArray(s.members)||!Array.isArray(s.slots)||!Array.isArray(s.traps)||!Array.isArray(s.blocks)||!Array.isArray(s.structures)||!s.settings)throw Error('This file is not a Bear Hive backup.');if(s.members.length>500||s.slots.length>1500||s.blocks.length>3000||s.structures.length>1000)throw Error('Plan exceeds supported size.');if(!Number.isFinite(s.settings.anchorX)||!Number.isFinite(s.settings.anchorY))throw Error('Invalid map coordinates.');const ids=new Set();for(const slot of s.slots){if(ids.has(slot.id)||![slot.x,slot.y,slot.w,slot.h].every(Number.isFinite)||slot.w!==2||slot.h!==2)throw Error('Invalid city slots.');ids.add(slot.id)}const assigned=new Set();const memberIds=new Set();for(const m of s.members){if(typeof m.name!=='string'||typeof m.id!=='string'||memberIds.has(m.id)||![0,1,2].includes(m.trap)||!m.attendance)throw Error('Invalid member data.');memberIds.add(m.id);if(m.slot&&(!ids.has(m.slot)||assigned.has(m.slot)))throw Error('Invalid or duplicate city assignment.');if(m.slot)assigned.add(m.slot)}for(const o of [...s.traps,...s.structures,...s.blocks])if(![o.x,o.y,o.w,o.h].every(Number.isFinite)||o.w<=0||o.h<=0)throw Error('Invalid map object.');return s}
function demo(){const traps=[{id:1,x:0,y:0,w:3,h:3},{id:2,x:24,y:0,w:3,h:3}],slots=slotsFor(traps);const names=['Caroline','Juniper','베리별','Atlas','Mochi','Suri','Pip','Night Owl','Луна','Koa','Mei 林','Nova','Rook','Sunny','أمل','Taro','Echo','Aster','Frostbyte','Juno','Arlo','Lily','별빛','Niko','Willow','Sol','Cloud','Yuki','Olive','Kai','Zora','Theo'];const members=names.map((name,i)=>{let trap=i<20?1:2;let pool=slots.filter(s=>s.trap===trap).sort((a,b)=>a.row-b.row||a.y-b.y||a.x-b.x);return{id:'demo-'+i,name,playerId:'',trap,role:i%5===0?'leader':'joiner',priority:0,attendance:{1:{kind:i%6===0?'sometimes':'regular',attended:null,total:null},2:{kind:i%4===0?'regular':'sometimes',attended:null,total:null}},slot:pool[(i<20?i:i-20)].id,current:i%3===0?null:{x:500+pool[(i<20?i:i-20)].x,y:500+pool[(i<20?i:i-20)].y},locked:false,confirmed:false,verified:false,joinSeconds:null,rallySeconds:null,notes:''}});return{version:1,settings:{alliance:'LUN',state:'3573',time1:'18:00',time2:'12:00',anchorX:500,anchorY:500,verified:false},traps,slots,members,blocks:[],structures:[],published:null}}
const api={overlap,center,attendance,attendanceText,slotsFor,coord,suggest,validate,demo};if(typeof module!=='undefined')module.exports=api;else root.Hive=api;
})(typeof window!=='undefined'?window:globalThis);
